Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
using namespace std;

#define LET(x, a)  __typeof(a) x(a)
#define TR(v, it) for(LET(it, v.begin()); it != v.end(); it++)
#define si(x) scanf("%d",&x)
#define F first
#define S second
#define PB push_back
#define MP make_pair
#define INF 1000000000
#define MOD 1000000007
#define SET(x,y) memset(x,y,sizeof(x));
#define LL long long int
#define ULL unsigned LL
#define PII pair<int, int>

class Matrix {
    public:
    int m[31][31];
    int N;
    Matrix(int N) {
        this->N = N;
        memset(m, 0, sizeof(m));
        for (int i = 0; i < N; i++)
            m[i][i] = 1;
    }
    Matrix* operator *(Matrix b);
} *M[71][31];
Matrix* Matrix::operator *(Matrix b) {
    int i, j, k;
    Matrix* ret = new Matrix(N);
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            LL cans = 0;
            for (k = 0; k < N; k++) {
                cans += m[i][k] * ((LL)b.m[k][j]);
                cans %= MOD;
            }
            ret->m[i][j] = cans;
        }
    }
    return ret;
}

LL kp[100];
int main() {
    int i, j, k, l;
    LL n;
    cin >> n >> k;
    for (i = 0; i < k; i++) {
        M[0][i] = new Matrix(k + 1);
        for (j = 0; j <= k; j++) {
            M[0][i]->m[i][j] = 1;
        }
    }
    kp[0] = 1;
    kp[1] = k;
    int lg = 2;
    while (kp[lg - 1] <= n / k) {
        kp[lg] = kp[lg - 1] * k;
        lg++;
    }
    for (i = 1; i < lg; i++) {
        M[i][0] = new Matrix(k + 1);
        for (j = 1; j < k; j++) {
            M[i][j] = *M[i - 1][j - 1] * *M[i][j - 1];
        }
        Matrix *cpro = new Matrix(k + 1);
        for (j = k - 1; j >= 0; j--) {
            cpro = *cpro * *M[i - 1][j];
            M[i][j] = *M[i][j] * *cpro;
        }
    }
    Matrix *ans = new Matrix(k + 1);
    int cc = 0;
    for (i = lg - 1; i >= 0; i--) {
        while (kp[i] <= n) {
            n -= kp[i];
            ans = *M[i][cc] * *ans;
            cc++;
            cc %= k;
        }
    }
    LL ret = 0;
    for (i = 0; i <= k; i++) {
        ret += ans->m[i][k];
        ret %= MOD;
    }
    cout << ret << endl;
    return 0;
}

